from functools import lru_cache

def fibfib(n: int):
    """
    Compute the n-th FibFib number.

    The FibFib sequence is defined as:
    fibfib(0) == 0
    fibfib(1) == 0
    fibfib(2) == 1
    fibfib(k) == fibfib(k-1) + fibfib(k-2) + fibfib(k-3) for k >= 3

    Uses memoization via lru_cache for efficiency.
    """
    @lru_cache(maxsize=None)
    def helper(k):
        if k == 0:
            return 0
        if k == 1:
            return 0
        if k == 2:
            return 1
        return helper(k - 1) + helper(k - 2) + helper(k - 3)

    return helper(n)
