import re

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exist
    split on commas. If neither exist, return the number of lower-case letters with odd alphabetical
    order (ord('a')=0, ..., ord('z')=25).
    '''
    # First check if there is whitespace (space, tab, newline, etc.)
    if any(char.isspace() for char in txt):
        # Split on any whitespace characters (default split handles this)
        return re.split(r'\s+', txt.strip())
    # If no whitespace, check for commas
    if ',' in txt:
        # Split only on commas (keep empty parts if any)
        return txt.split(',')
    # Otherwise, count lower-case letters with odd Unicode code point difference from 'a'
    count = 0
    for c in txt:
        if 'a' <= c <= 'z' and (ord(c) - ord('a')) % 2 == 1:
            count += 1
    return count
